const targets = {"app/usuarios-sistema/page.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { FormEvent, ReactNode, useEffect, useMemo, useState } from \"react\";\nimport { useUsuarioPermissoes } from \"@/app/Permissao\";\nimport {\n  GRUPOS_PERMISSOES,\n  permissoesPadraoPorPerfil,\n} from \"@/lib/permissoesSistema\";\n\ntype UsuarioSistema = {\n  id: string;\n  name: string;\n  username: string;\n  email?: string | null;\n  role: string;\n  status: string;\n  profitShareEnabled?: boolean;\n  profitSharePercent?: number | string | null;\n  permissions?: string[];\n  lastLoginAt?: string | null;\n  createdAt?: string | null;\n  updatedAt?: string | null;\n};\n\ntype FormUsuario = {\n  name: string;\n  username: string;\n  email: string;\n  password: string;\n  role: string;\n  status: string;\n  profitShareEnabled: boolean;\n  profitSharePercent: string;\n  permissions: string[];\n};\n\ntype FiltrosUsuario = {\n  busca: string;\n  role: string;\n  status: string;\n};\n\nconst FORM_INICIAL: FormUsuario = {\n  name: \"\",\n  username: \"\",\n  email: \"\",\n  password: \"\",\n  role: \"ATENDENTE\",\n  status: \"ATIVO\",\n  profitShareEnabled: false,\n  profitSharePercent: \"0\",\n  permissions: permissoesPadraoPorPerfil(\"ATENDENTE\"),\n};\n\nconst FILTROS_INICIAIS: FiltrosUsuario = {\n  busca: \"\",\n  role: \"TODOS\",\n  status: \"TODOS\",\n};\n\nconst CARGOS = [\n  { value: \"ADMIN\", label: \"Administrador\" },\n  { value: \"ATENDENTE\", label: \"Atendente\" },\n  { value: \"TECNICO\", label: \"Técnico\" },\n  { value: \"FINANCEIRO\", label: \"Financeiro\" },\n];\n\nconst STATUS_USUARIO = [\n  { value: \"ATIVO\", label: \"Ativo\" },\n  { value: \"INATIVO\", label: \"Inativo\" },\n  { value: \"BLOQUEADO\", label: \"Bloqueado\" },\n];\n\nconst nomesCargo: Record<string, string> = {\n  ADMIN: \"Administrador\",\n  ATENDENTE: \"Atendente\",\n  TECNICO: \"Técnico\",\n  FINANCEIRO: \"Financeiro\",\n};\n\nconst nomesStatus: Record<string, string> = {\n  ATIVO: \"Ativo\",\n  INATIVO: \"Inativo\",\n  BLOQUEADO: \"Bloqueado\",\n};\n\nconst inputClass =\n  \"w-full rounded-xl border border-slate-300 bg-white px-4 py-3 text-sm font-semibold outline-none transition focus:border-blue-500 focus:ring-4 focus:ring-blue-100 disabled:cursor-not-allowed disabled:bg-slate-100 disabled:text-slate-500\";\n\nfunction formatarDataHora(data?: string | null) {\n  if (!data) return \"-\";\n\n  const d = new Date(data);\n\n  if (Number.isNaN(d.getTime())) return \"-\";\n\n  return d.toLocaleString(\"pt-BR\");\n}\n\nfunction mensagemEhSucesso(mensagem: string) {\n  return mensagem.toLowerCase().includes(\"sucesso\");\n}\n\nfunction normalizarLogin(valor: string) {\n  return valor\n    .toLowerCase()\n    .trim()\n    .replace(/\\s+/g, \"\")\n    .replace(/[^a-z0-9._-]/g, \"\");\n}\n\nfunction emailValido(email: string) {\n  if (!email.trim()) return true;\n  return /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email.trim());\n}\n\nfunction classeStatus(status: string) {\n  if (status === \"ATIVO\") {\n    return \"bg-green-50 text-green-700 ring-green-600/20\";\n  }\n\n  if (status === \"BLOQUEADO\") {\n    return \"bg-red-50 text-red-700 ring-red-600/20\";\n  }\n\n  return \"bg-yellow-50 text-yellow-700 ring-yellow-600/20\";\n}\n\nfunction CardMensagem({ mensagem }: { mensagem: string }) {\n  if (!mensagem) return null;\n\n  return (\n    <div\n      className={`rounded-2xl p-4 text-sm font-bold ring-1 ${\n        mensagemEhSucesso(mensagem)\n          ? \"bg-green-50 text-green-700 ring-green-200\"\n          : \"bg-red-50 text-red-700 ring-red-200\"\n      }`}\n    >\n      {mensagem}\n    </div>\n  );\n}\n\nfunction CampoTexto({\n  label,\n  value,\n  onChange,\n  placeholder,\n  type = \"text\",\n  disabled = false,\n  required = false,\n  help,\n}: {\n  label: string;\n  value: string;\n  onChange: (valor: string) => void;\n  placeholder?: string;\n  type?: \"text\" | \"email\" | \"password\";\n  disabled?: boolean;\n  required?: boolean;\n  help?: string;\n}) {\n  return (\n    <div>\n      <label className=\"mb-1 block text-sm font-black text-slate-700\">\n        {label}\n        {required ? \" *\" : \"\"}\n      </label>\n\n      <input\n        type={type}\n        value={value}\n        disabled={disabled}\n        placeholder={placeholder}\n        onChange={(event) => onChange(event.target.value)}\n        className={inputClass}\n      />\n\n      {help && (\n        <p className=\"mt-2 text-xs font-semibold text-slate-500\">{help}</p>\n      )}\n    </div>\n  );\n}\n\nfunction CampoSelect({\n  label,\n  value,\n  onChange,\n  options,\n  disabled = false,\n  help,\n}: {\n  label: string;\n  value: string;\n  onChange: (valor: string) => void;\n  options: { value: string; label: string }[];\n  disabled?: boolean;\n  help?: string;\n}) {\n  return (\n    <div>\n      <label className=\"mb-1 block text-sm font-black text-slate-700\">\n        {label}\n      </label>\n\n      <select\n        value={value}\n        disabled={disabled}\n        onChange={(event) => onChange(event.target.value)}\n        className={inputClass}\n      >\n        {options.map((item) => (\n          <option key={item.value} value={item.value}>\n            {item.label}\n          </option>\n        ))}\n      </select>\n\n      {help && (\n        <p className=\"mt-2 text-xs font-semibold text-slate-500\">{help}</p>\n      )}\n    </div>\n  );\n}\n\nfunction CardResumo({\n  titulo,\n  valor,\n  detalhe,\n  destaque = \"slate\",\n}: {\n  titulo: string;\n  valor: ReactNode;\n  detalhe?: ReactNode;\n  destaque?: \"green\" | \"red\" | \"blue\" | \"slate\";\n}) {\n  const cor =\n    destaque === \"green\"\n      ? \"text-green-700\"\n      : destaque === \"red\"\n        ? \"text-red-700\"\n        : destaque === \"blue\"\n          ? \"text-blue-700\"\n          : \"text-slate-950\";\n\n  return (\n    <div className=\"rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200\">\n      <p className=\"text-sm font-bold text-slate-500\">{titulo}</p>\n\n      <strong className={`mt-2 block text-4xl ${cor}`}>{valor}</strong>\n\n      {detalhe && (\n        <div className=\"mt-2 text-sm font-semibold leading-6 text-slate-500\">\n          {detalhe}\n        </div>\n      )}\n    </div>\n  );\n}\n\nfunction LinhaInfo({\n  titulo,\n  children,\n}: {\n  titulo: string;\n  children: ReactNode;\n}) {\n  return (\n    <div className=\"rounded-xl bg-white p-3 ring-1 ring-slate-100\">\n      <p className=\"text-[10px] font-black uppercase tracking-wide text-slate-400\">\n        {titulo}\n      </p>\n\n      <div className=\"mt-1 text-xs font-bold text-slate-800\">{children}</div>\n    </div>\n  );\n}\n\nexport default function UsuariosSistemaPage() {\n  const { carregando: carregandoPermissoes, tem, usuario } =\n    useUsuarioPermissoes();\n\n  const podeVerDashboard = !carregandoPermissoes && tem(\"dashboard.ver\");\n\n  // Gestão de usuários é área crítica: a tela só abre para ADMIN.\n  const podeGerenciarUsuarios =\n    !carregandoPermissoes && usuario?.role === \"ADMIN\";\n\n  const [usuarios, setUsuarios] = useState<UsuarioSistema[]>([]);\n  const [usuarioSelecionado, setUsuarioSelecionado] =\n    useState<UsuarioSistema | null>(null);\n\n  const [form, setForm] = useState<FormUsuario>(FORM_INICIAL);\n  const [filtros, setFiltros] = useState<FiltrosUsuario>(FILTROS_INICIAIS);\n\n  const [carregando, setCarregando] = useState(true);\n  const [salvando, setSalvando] = useState(false);\n  const [excluindoId, setExcluindoId] = useState(\"\");\n  const [reaplicandoPermissoes, setReaplicandoPermissoes] = useState(false);\n  const [mensagem, setMensagem] = useState(\"\");\n\n  const resumo = useMemo(() => {\n    return {\n      total: usuarios.length,\n      ativos: usuarios.filter((usuario) => usuario.status === \"ATIVO\").length,\n      admins: usuarios.filter((usuario) => usuario.role === \"ADMIN\").length,\n      bloqueados: usuarios.filter((usuario) => usuario.status === \"BLOQUEADO\")\n        .length,\n    };\n  }, [usuarios]);\n\n  const editando = Boolean(usuarioSelecionado);\n  const bloqueandoForm = carregando || salvando;\n\n  function atualizarFiltro(campo: keyof FiltrosUsuario, valor: string) {\n    setFiltros((atual) => ({\n      ...atual,\n      [campo]: valor,\n    }));\n  }\n\n  function atualizarForm(\n    campo: Exclude<keyof FormUsuario, \"profitShareEnabled\">,\n    valor: string\n  ) {\n    setMensagem(\"\");\n\n    if (campo === \"role\") {\n      setForm((atual) => ({\n        ...atual,\n        role: valor,\n        profitShareEnabled:\n          valor === \"TECNICO\" ? atual.profitShareEnabled : false,\n        profitSharePercent:\n          valor === \"TECNICO\" ? atual.profitSharePercent : \"0\",\n        permissions: permissoesPadraoPorPerfil(valor),\n      }));\n\n      return;\n    }\n\n    setForm((atual) => ({\n      ...atual,\n      [campo]: valor,\n    }));\n  }\n\n  function limparForm() {\n    setUsuarioSelecionado(null);\n    setForm(FORM_INICIAL);\n    setMensagem(\"\");\n  }\n\n  function limparFiltros() {\n    setFiltros(FILTROS_INICIAIS);\n    carregarUsuarios(FILTROS_INICIAIS);\n  }\n\n  function editarUsuario(usuario: UsuarioSistema) {\n    setUsuarioSelecionado(usuario);\n    setMensagem(\"\");\n\n    setForm({\n      name: usuario.name || \"\",\n      username: usuario.username || \"\",\n      email: usuario.email || \"\",\n      password: \"\",\n      role: usuario.role || \"ATENDENTE\",\n      status: usuario.status || \"ATIVO\",\n      profitShareEnabled:\n        usuario.role === \"TECNICO\" && usuario.profitShareEnabled === true,\n      profitSharePercent:\n        usuario.role === \"TECNICO\"\n          ? String(Number(usuario.profitSharePercent || 0))\n          : \"0\",\n      permissions:\n        Array.isArray(usuario.permissions) && usuario.permissions.length > 0\n          ? usuario.permissions\n          : permissoesPadraoPorPerfil(usuario.role),\n    });\n\n    window.scrollTo({\n      top: 0,\n      behavior: \"smooth\",\n    });\n  }\n\n  function aplicarModeloPerfil() {\n    setForm((atual) => ({\n      ...atual,\n      permissions: permissoesPadraoPorPerfil(atual.role),\n    }));\n  }\n\n  function marcarTodasPermissoes() {\n    const todas = GRUPOS_PERMISSOES.flatMap((grupo) =>\n      grupo.permissoes.map((permissao) => permissao.key)\n    );\n\n    setForm((atual) => ({\n      ...atual,\n      permissions: Array.from(new Set(todas)),\n    }));\n  }\n\n  function limparPermissoes() {\n    setForm((atual) => ({\n      ...atual,\n      permissions: [],\n    }));\n  }\n\n  function alternarPermissao(key: string) {\n    setForm((atual) => {\n      const existe = atual.permissions.includes(key);\n\n      return {\n        ...atual,\n        permissions: existe\n          ? atual.permissions.filter((item) => item !== key)\n          : [...atual.permissions, key],\n      };\n    });\n  }\n\n  function grupoCompleto(keys: readonly string[]) {\n    return keys.every((key) => form.permissions.includes(key));\n  }\n\n  function alternarGrupo(keys: readonly string[]) {\n    const todasMarcadas = grupoCompleto(keys);\n\n    setForm((atual) => {\n      if (todasMarcadas) {\n        return {\n          ...atual,\n          permissions: atual.permissions.filter((key) => !keys.includes(key)),\n        };\n      }\n\n      return {\n        ...atual,\n        permissions: Array.from(new Set([...atual.permissions, ...keys])),\n      };\n    });\n  }\n\n  async function carregarUsuarios(filtrosBusca = filtros) {\n    if (!podeGerenciarUsuarios) {\n      setUsuarios([]);\n      setCarregando(false);\n      setMensagem(\"Apenas administradores podem gerenciar usuários.\");\n      return;\n    }\n\n    try {\n      setCarregando(true);\n      setMensagem(\"\");\n\n      const params = new URLSearchParams();\n\n      if (filtrosBusca.busca.trim()) {\n        params.set(\"busca\", filtrosBusca.busca.trim());\n      }\n\n      params.set(\"role\", filtrosBusca.role);\n      params.set(\"status\", filtrosBusca.status);\n\n      const response = await fetch(\n        `/api/usuarios-sistema?${params.toString()}`,\n        {\n          cache: \"no-store\",\n        }\n      );\n\n      const data = await response.json().catch(() => null);\n\n      if (!response.ok) {\n        setMensagem(data?.message || \"Erro ao carregar usuários.\");\n        setUsuarios([]);\n        return;\n      }\n\n      setUsuarios(Array.isArray(data?.usuarios) ? data.usuarios : []);\n    } catch {\n      setMensagem(\"Erro ao carregar usuários.\");\n      setUsuarios([]);\n    } finally {\n      setCarregando(false);\n    }\n  }\n\n  function validarFormulario() {\n    if (!form.name.trim()) {\n      return \"Informe o nome do usuário.\";\n    }\n\n    if (!editando && form.username.trim().length < 3) {\n      return \"O login precisa ter pelo menos 3 caracteres.\";\n    }\n\n    if (!editando && form.password.trim().length < 6) {\n      return \"A senha precisa ter pelo menos 6 caracteres.\";\n    }\n\n    if (editando && form.password.trim() && form.password.trim().length < 6) {\n      return \"A nova senha precisa ter pelo menos 6 caracteres.\";\n    }\n\n    if (!emailValido(form.email)) {\n      return \"Informe um e-mail válido.\";\n    }\n\n    if (form.role === \"TECNICO\" && form.profitShareEnabled) {\n      const percentual = Number(form.profitSharePercent);\n      if (!Number.isFinite(percentual) || percentual <= 0 || percentual > 100) {\n        return \"Informe um percentual de participação no lucro maior que 0 e até 100.\";\n      }\n    }\n\n    if (form.role !== \"ADMIN\" && form.permissions.length === 0) {\n      return \"Marque pelo menos uma permissão para o usuário.\";\n    }\n\n    return \"\";\n  }\n\n  async function salvarUsuario(event: FormEvent<HTMLFormElement>) {\n    event.preventDefault();\n    setMensagem(\"\");\n\n    const erro = validarFormulario();\n\n    if (erro) {\n      setMensagem(erro);\n      return;\n    }\n\n    try {\n      setSalvando(true);\n\n      const url = usuarioSelecionado\n        ? `/api/usuarios-sistema/${usuarioSelecionado.id}`\n        : \"/api/usuarios-sistema\";\n\n      const method = usuarioSelecionado ? \"PATCH\" : \"POST\";\n\n      const body = usuarioSelecionado\n        ? {\n            name: form.name.trim(),\n            email: form.email.trim().toLowerCase(),\n            password: form.password,\n            role: form.role,\n            status: form.status,\n            profitShareEnabled:\n              form.role === \"TECNICO\" && form.profitShareEnabled,\n            profitSharePercent:\n              form.role === \"TECNICO\" && form.profitShareEnabled\n                ? Number(form.profitSharePercent)\n                : 0,\n            permissions: form.permissions,\n          }\n        : {\n            ...form,\n            name: form.name.trim(),\n            username: normalizarLogin(form.username),\n            email: form.email.trim().toLowerCase(),\n            profitShareEnabled:\n              form.role === \"TECNICO\" && form.profitShareEnabled,\n            profitSharePercent:\n              form.role === \"TECNICO\" && form.profitShareEnabled\n                ? Number(form.profitSharePercent)\n                : 0,\n          };\n\n      const response = await fetch(url, {\n        method,\n        headers: {\n          \"Content-Type\": \"application/json\",\n        },\n        body: JSON.stringify(body),\n      });\n\n      const data = await response.json().catch(() => null);\n\n      if (!response.ok) {\n        setMensagem(data?.message || \"Erro ao salvar usuário.\");\n        return;\n      }\n\n      setMensagem(data?.message || \"Usuário salvo com sucesso.\");\n      limparForm();\n      await carregarUsuarios();\n    } catch {\n      setMensagem(\"Erro ao salvar usuário.\");\n    } finally {\n      setSalvando(false);\n    }\n  }\n\n  async function excluirUsuario(usuario: UsuarioSistema) {\n    \n  const confirmou = window.confirm(\n    `Tem certeza que deseja excluir o usuário \"${usuario.name}\"? Essa ação não pode ser desfeita.`\n  );\n\n  if (!confirmou) return;\n\n  try {\n    setMensagem(\"\");\n    setExcluindoId(usuario.id);\n\n    const response = await fetch(`/api/usuarios-sistema/${usuario.id}`, {\n      method: \"DELETE\",\n    });\n\n    const data = await response.json().catch(() => null);\n\n    if (!response.ok) {\n      setMensagem(data?.message || \"Erro ao excluir usuário.\");\n      return;\n    }\n\n    if (usuarioSelecionado?.id === usuario.id) {\n      limparForm();\n    }\n\n    setMensagem(data?.message || \"Usuário excluído com sucesso.\");\n    await carregarUsuarios();\n  } catch {\n    setMensagem(\"Erro ao excluir usuário.\");\n  } finally {\n    setExcluindoId(\"\");\n  }\n}\n\n  async function reaplicarPermissoesPadrao() {\n    const confirmou = window.confirm(\n      \"Deseja reaplicar as permissões padrão em todos os usuários? As permissões personalizadas serão substituídas pelo modelo da função de cada usuário.\"\n    );\n\n    if (!confirmou) return;\n\n    try {\n      setMensagem(\"\");\n      setReaplicandoPermissoes(true);\n\n      const response = await fetch(\n        \"/api/usuarios-sistema/reaplicar-permissoes\",\n        {\n          method: \"POST\",\n        }\n      );\n\n      const data = await response.json().catch(() => null);\n\n      if (!response.ok) {\n        setMensagem(data?.message || \"Erro ao reaplicar permissões padrão.\");\n        return;\n      }\n\n      limparForm();\n      setMensagem(data?.message || \"Permissões padrão reaplicadas com sucesso.\");\n      await carregarUsuarios();\n    } catch {\n      setMensagem(\"Erro ao reaplicar permissões padrão.\");\n    } finally {\n      setReaplicandoPermissoes(false);\n    }\n  }\n\n  useEffect(() => {\n    if (carregandoPermissoes) return;\n\n    if (!podeGerenciarUsuarios) {\n      setUsuarios([]);\n      setCarregando(false);\n      return;\n    }\n\n    carregarUsuarios();\n  }, [carregandoPermissoes, podeGerenciarUsuarios]);\n\n  if (carregandoPermissoes) {\n    return (\n      <main className=\"min-h-screen bg-slate-100 p-5 text-slate-950 lg:p-8\">\n        <section className=\"mx-auto max-w-7xl rounded-3xl bg-white p-6 text-sm font-bold text-slate-500 shadow-sm ring-1 ring-slate-200\">\n          Verificando permissões...\n        </section>\n      </main>\n    );\n  }\n\n  if (!podeGerenciarUsuarios) {\n    return (\n      <main className=\"min-h-screen bg-slate-100 p-5 text-slate-950 lg:p-8\">\n        <section className=\"mx-auto max-w-7xl space-y-4\">\n          <div className=\"rounded-3xl bg-white p-6 shadow-sm ring-1 ring-red-200\">\n            <p className=\"text-sm font-bold text-red-700\">\n              Apenas administradores podem acessar Usuários do Sistema.\n            </p>\n\n            <p className=\"mt-2 text-sm font-semibold leading-6 text-slate-500\">\n              A página foi bloqueada antes de carregar a lista de usuários.\n            </p>\n          </div>\n\n          <Link\n            href=\"/\"\n            className=\"inline-flex rounded-xl border border-slate-300 bg-white px-5 py-3 text-sm font-black text-slate-700 hover:bg-slate-50\"\n          >\n            Voltar para o painel\n          </Link>\n        </section>\n      </main>\n    );\n  }\n\n  return (\n    <main className=\"min-h-screen bg-slate-100 p-5 text-slate-950 lg:p-8\">\n      <section className=\"mx-auto max-w-7xl space-y-6\">\n        <header className=\"rounded-3xl bg-white p-6 shadow-sm ring-1 ring-slate-200\">\n          <div className=\"flex flex-col gap-4 md:flex-row md:items-center md:justify-between\">\n            <div>\n              <p className=\"text-sm font-bold text-blue-600\">\n                Controle de acesso\n              </p>\n\n              <h1 className=\"text-3xl font-black tracking-tight\">\n                Usuários do sistema\n              </h1>\n\n              <p className=\"mt-1 max-w-3xl text-sm font-semibold leading-6 text-slate-500\">\n                Cadastre operadores, defina perfis e controle permissões de\n                acesso ao sistema.\n              </p>\n            </div>\n\n            <div className=\"flex flex-wrap gap-2\">\n              {podeVerDashboard && (\n                <Link\n                  href=\"/\"\n                  className=\"rounded-xl border border-slate-300 bg-white px-5 py-3 text-sm font-black text-slate-700 shadow-sm hover:bg-slate-50\"\n                >\n                  Painel inicial\n                </Link>\n              )}\n\n              <button\n                type=\"button\"\n                onClick={reaplicarPermissoesPadrao}\n                disabled={carregando || salvando || reaplicandoPermissoes}\n                className=\"rounded-xl border border-blue-200 bg-blue-50 px-5 py-3 text-sm font-black text-blue-700 shadow-sm hover:bg-blue-100 disabled:cursor-not-allowed disabled:opacity-60\"\n              >\n                {reaplicandoPermissoes\n                  ? \"Reaplicando...\"\n                  : \"Reaplicar permissões\"}\n              </button>\n              \n              <button\n                type=\"button\"\n                onClick={() => carregarUsuarios()}\n                disabled={carregando}\n                className=\"rounded-xl bg-slate-950 px-5 py-3 text-sm font-black text-white shadow-sm hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-60\"\n              >\n                {carregando ? \"Atualizando...\" : \"Atualizar\"}\n              </button>\n            </div>\n          </div>\n        </header>\n\n        <CardMensagem mensagem={mensagem} />\n\n        <section className=\"grid gap-4 md:grid-cols-4\">\n          <CardResumo\n            titulo=\"Total de usuários\"\n            valor={resumo.total}\n            detalhe=\"Cadastros encontrados\"\n          />\n\n          <CardResumo\n            titulo=\"Ativos\"\n            valor={resumo.ativos}\n            detalhe=\"Podem acessar\"\n            destaque=\"green\"\n          />\n\n          <CardResumo\n            titulo=\"Administradores\"\n            valor={resumo.admins}\n            detalhe=\"Acesso completo\"\n            destaque=\"blue\"\n          />\n\n          <CardResumo\n            titulo=\"Bloqueados\"\n            valor={resumo.bloqueados}\n            detalhe=\"Sem acesso\"\n            destaque=\"red\"\n          />\n        </section>\n\n        <section className=\"grid gap-5 xl:grid-cols-[0.9fr_1.1fr]\">\n          <form\n            onSubmit={salvarUsuario}\n            className=\"rounded-3xl bg-white p-6 shadow-sm ring-1 ring-slate-200\"\n          >\n            <div className=\"mb-6 flex items-start justify-between gap-3\">\n              <div>\n                <p className=\"text-sm font-bold text-blue-600\">\n                  {editando ? \"Edição\" : \"Cadastro\"}\n                </p>\n\n                <h2 className=\"text-2xl font-black tracking-tight\">\n                  {editando\n                    ? `Editar @${usuarioSelecionado?.username}`\n                    : \"Novo usuário\"}\n                </h2>\n\n                <p className=\"mt-1 text-sm font-semibold leading-6 text-slate-500\">\n                  {editando\n                    ? \"Altere dados, perfil, status, senha ou permissões.\"\n                    : \"Crie um operador para acessar o sistema.\"}\n                </p>\n              </div>\n\n              {editando && (\n                <button\n                  type=\"button\"\n                  onClick={limparForm}\n                  disabled={salvando}\n                  className=\"rounded-xl border border-slate-300 bg-white px-4 py-2 text-xs font-black text-slate-700 hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-60\"\n                >\n                  Novo\n                </button>\n              )}\n            </div>\n\n            <div className=\"space-y-5\">\n              <div className=\"grid gap-4 md:grid-cols-2\">\n                <CampoTexto\n                  label=\"Nome\"\n                  required\n                  value={form.name}\n                  disabled={bloqueandoForm}\n                  onChange={(valor) => atualizarForm(\"name\", valor)}\n                  placeholder=\"Nome completo\"\n                />\n\n                <CampoTexto\n                  label=\"Login\"\n                  required={!editando}\n                  value={form.username}\n                  disabled={editando || bloqueandoForm}\n                  onChange={(valor) =>\n                    atualizarForm(\"username\", normalizarLogin(valor))\n                  }\n                  placeholder=\"exemplo: erick\"\n                  help={\n                    editando\n                      ? \"O login não pode ser alterado depois de criado.\"\n                      : \"Use letras, números, ponto, traço ou underline.\"\n                  }\n                />\n\n                <CampoTexto\n                  label=\"E-mail\"\n                  type=\"email\"\n                  value={form.email}\n                  disabled={bloqueandoForm}\n                  onChange={(valor) =>\n                    atualizarForm(\"email\", valor.trim().toLowerCase())\n                  }\n                  placeholder=\"usuario@email.com\"\n                />\n\n                <CampoTexto\n                  label={editando ? \"Nova senha\" : \"Senha\"}\n                  type=\"password\"\n                  required={!editando}\n                  value={form.password}\n                  disabled={bloqueandoForm}\n                  onChange={(valor) => atualizarForm(\"password\", valor)}\n                  placeholder={\n                    editando\n                      ? \"Vazio = manter senha atual\"\n                      : \"Mínimo 6 caracteres\"\n                  }\n                />\n\n                <CampoSelect\n                  label=\"Função principal\"\n                  value={form.role}\n                  disabled={bloqueandoForm}\n                  onChange={(valor) => atualizarForm(\"role\", valor)}\n                  options={CARGOS}\n                  help=\"Ao trocar a função, o sistema aplica permissões sugeridas.\"\n                />\n\n                <CampoSelect\n                  label=\"Status\"\n                  value={form.status}\n                  disabled={bloqueandoForm}\n                  onChange={(valor) => atualizarForm(\"status\", valor)}\n                  options={STATUS_USUARIO}\n                />\n              </div>\n\n              {form.role === \"TECNICO\" && (\n                <section className=\"rounded-2xl bg-blue-50 p-4 ring-1 ring-blue-200\">\n                  <div className=\"flex items-start gap-3\">\n                    <input\n                      id=\"profitShareEnabled\"\n                      type=\"checkbox\"\n                      checked={form.profitShareEnabled}\n                      disabled={bloqueandoForm}\n                      onChange={(event) => {\n                        setMensagem(\"\");\n                        setForm((atual) => ({\n                          ...atual,\n                          profitShareEnabled: event.target.checked,\n                          profitSharePercent: event.target.checked\n                            ? atual.profitSharePercent\n                            : \"0\",\n                        }));\n                      }}\n                      className=\"mt-1 h-4 w-4 rounded border-slate-300\"\n                    />\n\n                    <div className=\"min-w-0 flex-1\">\n                      <label\n                        htmlFor=\"profitShareEnabled\"\n                        className=\"cursor-pointer text-sm font-black text-blue-900\"\n                      >\n                        Participa do lucro das OS\n                      </label>\n                      <p className=\"mt-1 text-xs font-semibold leading-5 text-blue-700\">\n                        Quando a OS for marcada como Pronto, o percentual vigente\n                        será congelado na própria OS para preservar o histórico.\n                      </p>\n                    </div>\n                  </div>\n\n                  {form.profitShareEnabled && (\n                    <div className=\"mt-4 max-w-xs\">\n                      <label className=\"mb-1 block text-sm font-black text-slate-700\">\n                        Percentual do técnico *\n                      </label>\n                      <div className=\"relative\">\n                        <input\n                          type=\"number\"\n                          min=\"0.01\"\n                          max=\"100\"\n                          step=\"0.01\"\n                          value={form.profitSharePercent}\n                          disabled={bloqueandoForm}\n                          onChange={(event) =>\n                            atualizarForm(\n                              \"profitSharePercent\",\n                              event.target.value\n                            )\n                          }\n                          className={`${inputClass} pr-10`}\n                        />\n                        <span className=\"pointer-events-none absolute right-4 top-1/2 -translate-y-1/2 text-sm font-black text-slate-500\">\n                          %\n                        </span>\n                      </div>\n                      <p className=\"mt-2 text-xs font-semibold text-slate-500\">\n                        Permitido: maior que 0% e até 100%.\n                      </p>\n                    </div>\n                  )}\n                </section>\n              )}\n\n              <section className=\"rounded-2xl bg-slate-50 p-4 ring-1 ring-slate-100\">\n                <div className=\"mb-4 flex flex-col gap-3 md:flex-row md:items-center md:justify-between\">\n                  <div>\n                    <p className=\"text-sm font-black text-slate-900\">\n                      Permissões do usuário\n                    </p>\n\n                    <p className=\"text-xs font-semibold text-slate-500\">\n                      {form.role === \"ADMIN\"\n                        ? \"Administrador recebe acesso completo.\"\n                        : `${form.permissions.length} permissão(ões) marcada(s).`}\n                    </p>\n                  </div>\n\n                  <div className=\"flex flex-wrap gap-2\">\n                    <button\n                      type=\"button\"\n                      onClick={aplicarModeloPerfil}\n                      disabled={bloqueandoForm}\n                      className=\"rounded-lg border border-slate-300 bg-white px-3 py-2 text-[11px] font-black text-slate-700 hover:bg-slate-100 disabled:cursor-not-allowed disabled:opacity-60\"\n                    >\n                      Modelo da função\n                    </button>\n\n                    <button\n                      type=\"button\"\n                      onClick={marcarTodasPermissoes}\n                      disabled={bloqueandoForm}\n                      className=\"rounded-lg bg-slate-950 px-3 py-2 text-[11px] font-black text-white hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-60\"\n                    >\n                      Marcar tudo\n                    </button>\n\n                    <button\n                      type=\"button\"\n                      onClick={limparPermissoes}\n                      disabled={bloqueandoForm || form.role === \"ADMIN\"}\n                      className=\"rounded-lg bg-red-600 px-3 py-2 text-[11px] font-black text-white hover:bg-red-700 disabled:cursor-not-allowed disabled:opacity-60\"\n                    >\n                      Limpar\n                    </button>\n                  </div>\n                </div>\n\n                <div className=\"max-h-[560px] space-y-3 overflow-auto pr-1\">\n                  {GRUPOS_PERMISSOES.map((grupo) => {\n                    const keys = grupo.permissoes.map(\n                      (permissao) => permissao.key\n                    );\n\n                    const todasMarcadas = grupoCompleto(keys);\n\n                    return (\n                      <div\n                        key={grupo.titulo}\n                        className=\"rounded-2xl bg-white p-4 ring-1 ring-slate-100\"\n                      >\n                        <div className=\"mb-3 flex items-center justify-between gap-3\">\n                          <h3 className=\"text-sm font-black text-slate-900\">\n                            {grupo.titulo}\n                          </h3>\n\n                          <button\n                            type=\"button\"\n                            onClick={() => alternarGrupo(keys)}\n                            disabled={bloqueandoForm || form.role === \"ADMIN\"}\n                            className=\"rounded-lg border border-slate-200 bg-slate-50 px-3 py-1.5 text-[11px] font-black text-slate-700 hover:bg-slate-100 disabled:cursor-not-allowed disabled:opacity-60\"\n                          >\n                            {todasMarcadas ? \"Desmarcar grupo\" : \"Marcar grupo\"}\n                          </button>\n                        </div>\n\n                        <div className=\"grid gap-2 md:grid-cols-2\">\n                          {grupo.permissoes.map((permissao) => (\n                            <label\n                              key={permissao.key}\n                              className=\"flex cursor-pointer items-center gap-2 rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-xs font-bold text-slate-700 hover:bg-slate-100\"\n                            >\n                              <input\n                                type=\"checkbox\"\n                                checked={form.permissions.includes(\n                                  permissao.key\n                                )}\n                                disabled={bloqueandoForm || form.role === \"ADMIN\"}\n                                onChange={() =>\n                                  alternarPermissao(permissao.key)\n                                }\n                                className=\"h-4 w-4 rounded border-slate-300\"\n                              />\n\n                              <span>{permissao.label}</span>\n                            </label>\n                          ))}\n                        </div>\n                      </div>\n                    );\n                  })}\n                </div>\n              </section>\n\n              <button\n                type=\"submit\"\n                disabled={salvando}\n                className=\"w-full rounded-xl bg-blue-600 px-5 py-4 text-sm font-black text-white shadow-lg shadow-blue-600/20 hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-60\"\n              >\n                {salvando\n                  ? \"Salvando...\"\n                  : editando\n                    ? \"Salvar usuário\"\n                    : \"Criar usuário\"}\n              </button>\n            </div>\n          </form>\n\n          <section className=\"rounded-3xl bg-white p-6 shadow-sm ring-1 ring-slate-200\">\n            <div className=\"mb-5\">\n              <p className=\"text-sm font-bold text-blue-600\">Consulta</p>\n\n              <h2 className=\"text-2xl font-black tracking-tight\">\n                Lista de usuários\n              </h2>\n\n              <p className=\"mt-1 text-sm font-semibold text-slate-500\">\n                Busque por nome, login, e-mail, perfil ou status.\n              </p>\n            </div>\n\n            <div className=\"mb-5 grid gap-3 lg:grid-cols-[1fr_0.55fr_0.55fr_auto_auto]\">\n              <input\n                value={filtros.busca}\n                disabled={carregando}\n                onChange={(event) => atualizarFiltro(\"busca\", event.target.value)}\n                placeholder=\"Nome, login ou e-mail\"\n                className={inputClass}\n              />\n\n              <select\n                value={filtros.role}\n                disabled={carregando}\n                onChange={(event) => atualizarFiltro(\"role\", event.target.value)}\n                className={inputClass}\n              >\n                <option value=\"TODOS\">Todos perfis</option>\n                {CARGOS.map((cargo) => (\n                  <option key={cargo.value} value={cargo.value}>\n                    {cargo.label}\n                  </option>\n                ))}\n              </select>\n\n              <select\n                value={filtros.status}\n                disabled={carregando}\n                onChange={(event) =>\n                  atualizarFiltro(\"status\", event.target.value)\n                }\n                className={inputClass}\n              >\n                <option value=\"TODOS\">Todos status</option>\n                {STATUS_USUARIO.map((status) => (\n                  <option key={status.value} value={status.value}>\n                    {status.label}\n                  </option>\n                ))}\n              </select>\n\n              <button\n                type=\"button\"\n                onClick={() => carregarUsuarios()}\n                disabled={carregando}\n                className=\"rounded-xl bg-slate-950 px-5 py-3 text-sm font-black text-white hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-60\"\n              >\n                {carregando ? \"Buscando...\" : \"Buscar\"}\n              </button>\n\n              <button\n                type=\"button\"\n                onClick={limparFiltros}\n                disabled={carregando}\n                className=\"rounded-xl border border-slate-300 bg-white px-5 py-3 text-sm font-black text-slate-700 hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-60\"\n              >\n                Limpar\n              </button>\n            </div>\n\n            {carregando ? (\n              <div className=\"rounded-2xl border border-dashed border-slate-300 bg-slate-50 p-6 text-center text-sm font-bold text-slate-500\">\n                Carregando usuários...\n              </div>\n            ) : usuarios.length === 0 ? (\n              <div className=\"rounded-2xl border border-dashed border-slate-300 bg-slate-50 p-6 text-center text-sm font-bold text-slate-500\">\n                Nenhum usuário encontrado.\n              </div>\n            ) : (\n              <div className=\"space-y-3\">\n                {usuarios.map((usuario) => (\n                  <article\n                    key={usuario.id}\n                    className={`rounded-2xl p-4 ring-1 ${\n                      usuarioSelecionado?.id === usuario.id\n                        ? \"bg-blue-50 ring-blue-200\"\n                        : \"bg-slate-50 ring-slate-100\"\n                    }`}\n                  >\n                    <div className=\"flex flex-col gap-3 md:flex-row md:items-start md:justify-between\">\n                      <div>\n                        <div className=\"flex flex-wrap items-center gap-2\">\n                          <h3 className=\"text-base font-black\">\n                            {usuario.name}\n                          </h3>\n\n                          <span\n                            className={`rounded-full px-3 py-1 text-[11px] font-black ring-1 ${classeStatus(\n                              usuario.status\n                            )}`}\n                          >\n                            {nomesStatus[usuario.status] || usuario.status}\n                          </span>\n\n                          {usuario.role === \"ADMIN\" && (\n                            <span className=\"rounded-full bg-slate-950 px-3 py-1 text-[11px] font-black text-white\">\n                              Admin\n                            </span>\n                          )}\n                        </div>\n\n                        <p className=\"mt-1 text-xs font-bold text-slate-500\">\n                          @{usuario.username} |{\" \"}\n                          {nomesCargo[usuario.role] || usuario.role}\n                        </p>\n\n                        <p className=\"mt-1 text-xs font-semibold text-slate-500\">\n                          {usuario.email || \"Sem e-mail\"}\n                        </p>\n\n                        <p className=\"mt-2 text-xs font-black text-blue-600\">\n                          {usuario.permissions?.length || 0} permissão(ões)\n                        </p>\n\n                        {usuario.role === \"TECNICO\" && (\n                          <p className=\"mt-1 text-xs font-black text-emerald-700\">\n                            Participação no lucro:{\" \"}\n                            {usuario.profitShareEnabled\n                              ? `${Number(usuario.profitSharePercent || 0).toLocaleString(\n                                  \"pt-BR\",\n                                  { maximumFractionDigits: 2 }\n                                )}%`\n                              : \"desativada\"}\n                          </p>\n                        )}\n                      </div>\n\n                      <div className=\"flex flex-wrap gap-2 md:justify-end\">\n  <button\n    type=\"button\"\n    onClick={() => editarUsuario(usuario)}\n    disabled={salvando || Boolean(excluindoId)}\n    className=\"rounded-xl bg-blue-600 px-4 py-2 text-xs font-black text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-60\"\n  >\n    Editar\n  </button>\n\n  <button\n    type=\"button\"\n    onClick={() => excluirUsuario(usuario)}\n    disabled={salvando || excluindoId === usuario.id}\n    className=\"rounded-xl bg-red-600 px-4 py-2 text-xs font-black text-white hover:bg-red-700 disabled:cursor-not-allowed disabled:opacity-60\"\n  >\n    {excluindoId === usuario.id ? \"Excluindo...\" : \"Excluir\"}\n  </button>\n</div>\n                    </div>\n\n                    <div className=\"mt-3 grid gap-3 md:grid-cols-2\">\n                      <LinhaInfo titulo=\"Último login\">\n                        {formatarDataHora(usuario.lastLoginAt)}\n                      </LinhaInfo>\n\n                      <LinhaInfo titulo=\"Criado em\">\n                        {formatarDataHora(usuario.createdAt)}\n                      </LinhaInfo>\n                    </div>\n                  </article>\n                ))}\n              </div>\n            )}\n          </section>\n        </section>\n      </section>\n    </main>\n  );\n}", "app/api/usuarios-sistema/route.ts": "import { NextResponse } from \"next/server\";\nimport { SystemUserRole, SystemUserStatus, type Prisma } from \"@prisma/client\";\nimport { prisma } from \"@/lib/prisma\";\nimport { criarHashSenha } from \"@/lib/authSistema\";\nimport {\n  email,\n  emailValido,\n  exigirGerenciarUsuarios,\n  formatarUsuarioSistema,\n  login,\n  loginValido,\n  participacaoLucroParaSalvar,\n  permissoesParaSalvar,\n  respostaErro,\n  roleValida,\n  selectUsuarioSistema,\n  statusValido,\n  texto,\n} from \"@/lib/server/usuariosSistemaCore\";\n\nexport const runtime = \"nodejs\";\nexport const dynamic = \"force-dynamic\";\n\nexport async function GET(request: Request) {\n  try {\n    const acesso = await exigirGerenciarUsuarios();\n\n    if (!acesso.ok) {\n      return acesso.response;\n    }\n\n    if (acesso.usuario.role !== SystemUserRole.ADMIN) {\n      return respostaErro(\"Apenas administradores podem gerenciar usuários.\", 403);\n    }\n\n    const { searchParams } = new URL(request.url);\n\n    const busca = texto(searchParams.get(\"busca\"));\n    const roleParam = texto(searchParams.get(\"role\"));\n    const statusParam = texto(searchParams.get(\"status\"));\n\n    const where: Prisma.SystemUserWhereInput = {};\n\n    if (busca) {\n      where.OR = [\n        {\n          name: {\n            contains: busca,\n          },\n        },\n        {\n          username: {\n            contains: busca.toLowerCase(),\n          },\n        },\n        {\n          email: {\n            contains: busca.toLowerCase(),\n          },\n        },\n      ];\n    }\n\n    if (roleParam && roleParam !== \"TODOS\") {\n      const role = roleValida(roleParam);\n\n      if (!role) {\n        return respostaErro(\"Perfil de usuario invalido.\");\n      }\n\n      where.role = role;\n    }\n\n    if (statusParam && statusParam !== \"TODOS\") {\n      const status = statusValido(statusParam);\n\n      if (!status) {\n        return respostaErro(\"Status de usuario invalido.\");\n      }\n\n      where.status = status;\n    }\n\n    const usuarios = await prisma.systemUser.findMany({\n      where,\n      orderBy: {\n        createdAt: \"desc\",\n      },\n      select: selectUsuarioSistema,\n    });\n\n    return NextResponse.json({\n      usuarios: usuarios.map(formatarUsuarioSistema),\n    });\n  } catch (error) {\n    console.error(\"Erro ao listar usuarios:\", error);\n\n    return NextResponse.json(\n      {\n        message: \"Erro ao listar usuarios.\",\n      },\n      { status: 500 }\n    );\n  }\n}\n\nexport async function POST(request: Request) {\n  try {\n    const acesso = await exigirGerenciarUsuarios();\n\n    if (!acesso.ok) {\n      return acesso.response;\n    }\n\n    if (acesso.usuario.role !== SystemUserRole.ADMIN) {\n      return respostaErro(\"Apenas administradores podem gerenciar usuários.\", 403);\n    }\n\n    const body = await request.json().catch(() => null);\n\n    const name = texto(body?.name);\n    const username = login(body?.username);\n    const userEmail = email(body?.email);\n    const password = texto(body?.password);\n    const role = roleValida(body?.role) || SystemUserRole.ATENDENTE;\n    const status = statusValido(body?.status) || SystemUserStatus.ATIVO;\n    const permissions = permissoesParaSalvar(body?.permissions, role);\n    const profitShare = participacaoLucroParaSalvar(body, role);\n\n    if (!profitShare) {\n      return respostaErro(\n        \"Informe um percentual de participação no lucro maior que 0 e até 100.\"\n      );\n    }\n\n    if (!name) {\n      return respostaErro(\"Informe o nome do usuario.\");\n    }\n\n    if (!username || username.length < 3) {\n      return respostaErro(\"O login precisa ter pelo menos 3 caracteres.\");\n    }\n\n    if (!loginValido(username)) {\n      return respostaErro(\n        \"Use apenas letras, numeros, ponto, traco ou underline no login.\"\n      );\n    }\n\n    if (!password || password.length < 6) {\n      return respostaErro(\"A senha precisa ter pelo menos 6 caracteres.\");\n    }\n\n    if (!emailValido(userEmail)) {\n      return respostaErro(\"Informe um e-mail valido.\");\n    }\n\n    if (role !== SystemUserRole.ADMIN && permissions.length === 0) {\n      return respostaErro(\"Marque pelo menos uma permissao para o usuario.\");\n    }\n\n    const usuarioExistente = await prisma.systemUser.findFirst({\n      where: {\n        OR: [\n          {\n            username,\n          },\n          ...(userEmail\n            ? [\n                {\n                  email: userEmail,\n                },\n              ]\n            : []),\n        ],\n      },\n      select: {\n        username: true,\n        email: true,\n      },\n    });\n\n    if (usuarioExistente) {\n      return respostaErro(\n        usuarioExistente.username === username\n          ? \"Ja existe um usuario com esse login.\"\n          : \"Ja existe um usuario com esse e-mail.\"\n      );\n    }\n\n    const usuario = await prisma.systemUser.create({\n      data: {\n        name,\n        username,\n        email: userEmail,\n        passwordHash: criarHashSenha(password),\n        role,\n        status,\n        profitShareEnabled: profitShare.enabled,\n        profitSharePercent: profitShare.percent,\n        permissions: {\n          create: permissions.map((key) => ({\n            key,\n          })),\n        },\n      },\n      select: selectUsuarioSistema,\n    });\n\n    return NextResponse.json(\n      {\n        message: \"Usuario criado com sucesso.\",\n        usuario: formatarUsuarioSistema(usuario),\n      },\n      { status: 201 }\n    );\n  } catch (error) {\n    console.error(\"Erro ao criar usuario:\", error);\n\n    return NextResponse.json(\n      {\n        message: \"Erro ao criar usuario.\",\n      },\n      { status: 500 }\n    );\n  }\n}", "app/api/usuarios-sistema/[id]/route.ts": "import { NextResponse } from \"next/server\";\nimport { SystemUserRole, SystemUserStatus, type Prisma } from \"@prisma/client\";\nimport { prisma } from \"@/lib/prisma\";\nimport { criarHashSenha } from \"@/lib/authSistema\";\nimport {\n  email,\n  emailValido,\n  exigirGerenciarUsuarios,\n  formatarUsuarioSistema,\n  participacaoLucroParaSalvar,\n  permissoesParaSalvar,\n  respostaErro,\n  roleValida,\n  selectUsuarioSistema,\n  statusValido,\n  texto,\n} from \"@/lib/server/usuariosSistemaCore\";\n\nexport const runtime = \"nodejs\";\nexport const dynamic = \"force-dynamic\";\n\ntype RouteContext = {\n  params: Promise<{\n    id: string;\n  }>;\n};\n\nasync function existeOutroAdminAtivo(id: string) {\n  const total = await prisma.systemUser.count({\n    where: {\n      id: {\n        not: id,\n      },\n      role: SystemUserRole.ADMIN,\n      status: SystemUserStatus.ATIVO,\n    },\n  });\n\n  return total > 0;\n}\n\nexport async function PATCH(request: Request, context: RouteContext) {\n  try {\n    \n    const acesso = await exigirGerenciarUsuarios();\n\n    if (!acesso.ok) {\n      return acesso.response;\n    }\n\n    if (acesso.usuario.role !== SystemUserRole.ADMIN) {\n      return respostaErro(\"Apenas administradores podem gerenciar usuários.\", 403);\n    }\n\n    const { id } = await context.params;\n    const body = await request.json().catch(() => null);\n\n    if (!id) {\n      return respostaErro(\"ID do usuario nao informado.\");\n    }\n\n    const name = texto(body?.name);\n    const userEmail = email(body?.email);\n    const role = roleValida(body?.role) || SystemUserRole.ATENDENTE;\n    const status = statusValido(body?.status) || SystemUserStatus.ATIVO;\n    const novaSenha = texto(body?.password);\n    const permissions = permissoesParaSalvar(body?.permissions, role);\n    const profitShare = participacaoLucroParaSalvar(body, role);\n\n    if (!profitShare) {\n      return respostaErro(\n        \"Informe um percentual de participação no lucro maior que 0 e até 100.\"\n      );\n    }\n\n    if (!name) {\n      return respostaErro(\"Informe o nome do usuario.\");\n    }\n\n    if (!emailValido(userEmail)) {\n      return respostaErro(\"Informe um e-mail valido.\");\n    }\n\n    if (role !== SystemUserRole.ADMIN && permissions.length === 0) {\n      return respostaErro(\"Marque pelo menos uma permissao para o usuario.\");\n    }\n\n    const usuarioAtual = await prisma.systemUser.findUnique({\n      where: {\n        id,\n      },\n      select: {\n        id: true,\n        role: true,\n        status: true,\n      },\n    });\n\n    if (!usuarioAtual) {\n      return respostaErro(\"Usuario nao encontrado.\", 404);\n    }\n\n    const editandoProprioUsuario = acesso.usuario.id === id;\n\n    if (editandoProprioUsuario && status !== SystemUserStatus.ATIVO) {\n      return respostaErro(\n        \"Voce nao pode bloquear ou inativar seu proprio usuario.\"\n      );\n    }\n\n    if (editandoProprioUsuario && role !== SystemUserRole.ADMIN) {\n      return respostaErro(\n        \"Voce nao pode remover seu proprio perfil de administrador.\"\n      );\n    }\n\n    if (\n      editandoProprioUsuario &&\n      role !== SystemUserRole.ADMIN &&\n      !permissions.includes(\"usuarios.gerenciar\")\n    ) {\n      return respostaErro(\n        \"Voce nao pode remover sua propria permissao de gerenciar usuarios.\"\n      );\n    }\n\n    const removendoAdminAtivo =\n      usuarioAtual.role === SystemUserRole.ADMIN &&\n      usuarioAtual.status === SystemUserStatus.ATIVO &&\n      (role !== SystemUserRole.ADMIN || status !== SystemUserStatus.ATIVO);\n\n    if (removendoAdminAtivo) {\n      const temOutroAdminAtivo = await existeOutroAdminAtivo(id);\n\n      if (!temOutroAdminAtivo) {\n        return respostaErro(\n          \"Nao e permitido deixar o sistema sem administrador ativo.\"\n        );\n      }\n    }\n\n    if (userEmail) {\n      const emailDuplicado = await prisma.systemUser.findFirst({\n        where: {\n          id: {\n            not: id,\n          },\n          email: userEmail,\n        },\n        select: {\n          id: true,\n        },\n      });\n\n      if (emailDuplicado) {\n        return respostaErro(\"Ja existe outro usuario com esse e-mail.\");\n      }\n    }\n\n    const data: Prisma.SystemUserUpdateInput = {\n      name,\n      email: userEmail,\n      role,\n      status,\n      profitShareEnabled: profitShare.enabled,\n      profitSharePercent: profitShare.percent,\n      permissions: {\n        deleteMany: {},\n        create: permissions.map((key) => ({\n          key,\n        })),\n      },\n    };\n\n    if (novaSenha) {\n      if (novaSenha.length < 6) {\n        return respostaErro(\"A nova senha precisa ter pelo menos 6 caracteres.\");\n      }\n\n      data.passwordHash = criarHashSenha(novaSenha);\n    }\n\n    const usuario = await prisma.systemUser.update({\n      where: {\n        id,\n      },\n      data,\n      select: selectUsuarioSistema,\n    });\n\n    return NextResponse.json({\n      message: \"Usuario atualizado com sucesso.\",\n      usuario: formatarUsuarioSistema(usuario),\n    });\n  } catch (error) {\n    console.error(\"Erro ao atualizar usuario:\", error);\n\n    return NextResponse.json(\n      {\n        message: \"Erro ao atualizar usuario.\",\n      },\n      { status: 500 }\n    );\n  }\n}\nexport async function DELETE(_request: Request, context: RouteContext) {\n  try {\n    const acesso = await exigirGerenciarUsuarios();\n\n    if (!acesso.ok) {\n      return acesso.response;\n    }\n\n    if (acesso.usuario.role !== SystemUserRole.ADMIN) {\n      return respostaErro(\n        \"Apenas administradores podem excluir usuários.\",\n        403\n      );\n    }\n\n    const { id } = await context.params;\n\n    if (!id) {\n      return respostaErro(\"ID do usuário não informado.\");\n    }\n\n    if (acesso.usuario.id === id) {\n      return respostaErro(\"Você não pode excluir seu próprio usuário.\");\n    }\n\n    const usuarioAtual = await prisma.systemUser.findUnique({\n      where: {\n        id,\n      },\n      select: {\n        id: true,\n        name: true,\n        role: true,\n        status: true,\n      },\n    });\n\n    if (!usuarioAtual) {\n      return respostaErro(\"Usuário não encontrado.\", 404);\n    }\n\n    const removendoAdminAtivo =\n      usuarioAtual.role === SystemUserRole.ADMIN &&\n      usuarioAtual.status === SystemUserStatus.ATIVO;\n\n    if (removendoAdminAtivo) {\n      const temOutroAdminAtivo = await existeOutroAdminAtivo(id);\n\n      if (!temOutroAdminAtivo) {\n        return respostaErro(\n          \"Não é permitido deixar o sistema sem administrador ativo.\"\n        );\n      }\n    }\n\n    await prisma.$transaction(async (tx) => {\n      await tx.systemUser.update({\n        where: {\n          id,\n        },\n        data: {\n          permissions: {\n            deleteMany: {},\n          },\n        },\n        select: {\n          id: true,\n        },\n      });\n\n      await tx.systemUser.delete({\n        where: {\n          id,\n        },\n      });\n    });\n\n    return NextResponse.json({\n      message: \"Usuário excluído com sucesso.\",\n    });\n  } catch (error) {\n    console.error(\"Erro ao excluir usuário:\", error);\n\n    return NextResponse.json(\n      {\n        message: \"Erro ao excluir usuário.\",\n      },\n      { status: 500 }\n    );\n  }\n}", "lib/server/usuariosSistemaCore.ts": "import { NextResponse } from \"next/server\";\nimport {\n  SystemUserRole,\n  SystemUserStatus,\n  type SystemUser,\n} from \"@prisma/client\";\nimport { obterUsuarioLogado } from \"@/lib/authSistema\";\nimport {\n  normalizarPermissoes,\n  TODAS_PERMISSOES,\n} from \"@/lib/permissoesSistema\";\n\nexport const selectUsuarioSistema = {\n  id: true,\n  name: true,\n  username: true,\n  email: true,\n  role: true,\n  status: true,\n  profitShareEnabled: true,\n  profitSharePercent: true,\n  lastLoginAt: true,\n  createdAt: true,\n  updatedAt: true,\n  permissions: {\n    select: {\n      key: true,\n    },\n  },\n} as const;\n\ntype UsuarioComPermissoes = {\n  id: string;\n  name: string;\n  username: string;\n  role: string;\n  status: string;\n  permissions?: string[];\n};\n\ntype UsuarioFormatavel = Pick<\n  SystemUser,\n  | \"id\"\n  | \"name\"\n  | \"username\"\n  | \"email\"\n  | \"role\"\n  | \"status\"\n  | \"profitShareEnabled\"\n  | \"profitSharePercent\"\n  | \"lastLoginAt\"\n  | \"createdAt\"\n  | \"updatedAt\"\n> & {\n  permissions: {\n    key: string;\n  }[];\n};\n\nexport function texto(valor: unknown) {\n  return String(valor || \"\").trim();\n}\n\nexport function email(valor: unknown) {\n  const limpo = texto(valor).toLowerCase();\n  return limpo || null;\n}\n\nexport function login(valor: unknown) {\n  return texto(valor).toLowerCase();\n}\n\nexport function emailValido(valor: string | null) {\n  if (!valor) return true;\n\n  return /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(valor);\n}\n\nexport function loginValido(valor: string) {\n  return /^[a-z0-9._-]+$/.test(valor);\n}\n\nexport function roleValida(valor: unknown): SystemUserRole | null {\n  const role = texto(valor).toUpperCase();\n\n  if (role === SystemUserRole.ADMIN) return SystemUserRole.ADMIN;\n  if (role === SystemUserRole.ATENDENTE) return SystemUserRole.ATENDENTE;\n  if (role === SystemUserRole.TECNICO) return SystemUserRole.TECNICO;\n  if (role === SystemUserRole.FINANCEIRO) return SystemUserRole.FINANCEIRO;\n\n  return null;\n}\n\nexport function statusValido(valor: unknown): SystemUserStatus | null {\n  const status = texto(valor).toUpperCase();\n\n  if (status === SystemUserStatus.ATIVO) return SystemUserStatus.ATIVO;\n  if (status === SystemUserStatus.INATIVO) return SystemUserStatus.INATIVO;\n  if (status === SystemUserStatus.BLOQUEADO) return SystemUserStatus.BLOQUEADO;\n\n  return null;\n}\n\nexport type ProfitShareConfig = {\n  enabled: boolean;\n  percent: number;\n};\n\nexport function participacaoLucroParaSalvar(\n  valor: unknown,\n  role: SystemUserRole,\n): ProfitShareConfig | null {\n  if (role !== SystemUserRole.TECNICO) {\n    return { enabled: false, percent: 0 };\n  }\n\n  const body =\n    valor && typeof valor === \"object\" && !Array.isArray(valor)\n      ? (valor as Record<string, unknown>)\n      : {};\n\n  const enabled = body.profitShareEnabled === true;\n  if (!enabled) return { enabled: false, percent: 0 };\n\n  const recebido = Number(body.profitSharePercent);\n  if (!Number.isFinite(recebido) || recebido <= 0 || recebido > 100) {\n    return null;\n  }\n\n  return {\n    enabled: true,\n    percent: Math.round(recebido * 100) / 100,\n  };\n}\n\nexport function permissoesParaSalvar(valor: unknown, role: SystemUserRole) {\n  if (role === SystemUserRole.ADMIN) {\n    return [...TODAS_PERMISSOES];\n  }\n\n  return normalizarPermissoes(valor, role);\n}\n\nexport function formatarUsuarioSistema(usuario: UsuarioFormatavel) {\n  const { permissions, profitSharePercent, ...dados } = usuario;\n\n  const permissoes =\n    dados.role === SystemUserRole.ADMIN\n      ? [...TODAS_PERMISSOES]\n      : permissions.map((item) => item.key);\n\n  const tecnico = dados.role === SystemUserRole.TECNICO;\n  const profitShareEnabled = tecnico && Boolean(dados.profitShareEnabled);\n\n  return {\n    ...dados,\n    profitShareEnabled,\n    profitSharePercent: profitShareEnabled ? Number(profitSharePercent || 0) : 0,\n    permissions: permissoes,\n  };\n}\n\nexport function usuarioPodeGerenciarUsuarios(\n  usuario: UsuarioComPermissoes | null\n) {\n  if (!usuario) return false;\n\n  if (usuario.role === SystemUserRole.ADMIN) return true;\n\n  const permissoes = Array.isArray(usuario.permissions)\n    ? usuario.permissions\n    : [];\n\n  return permissoes.includes(\"usuarios.gerenciar\");\n}\n\nexport async function exigirGerenciarUsuarios() {\n  const usuario = await obterUsuarioLogado();\n\n  if (!usuario) {\n    return {\n      ok: false as const,\n      response: NextResponse.json(\n        {\n          message: \"Usuario nao autenticado.\",\n        },\n        { status: 401 }\n      ),\n    };\n  }\n\n  if (!usuarioPodeGerenciarUsuarios(usuario)) {\n    return {\n      ok: false as const,\n      response: NextResponse.json(\n        {\n          message: \"Voce nao tem permissao para gerenciar usuarios.\",\n        },\n        { status: 403 }\n      ),\n    };\n  }\n\n  return {\n    ok: true as const,\n    usuario,\n  };\n}\n\nexport function respostaErro(message: string, status = 400) {\n  return NextResponse.json(\n    {\n      message,\n    },\n    {\n      status,\n    }\n  );\n}"};
const testFile = "scripts/test-estoque-tecnico/etapa3c5b-config-tecnico.cjs";
const testContent = "#!/usr/bin/env node\n\"use strict\";\nconst assert = require(\"node:assert/strict\");\nconst fs = require(\"node:fs\");\nconst path = require(\"node:path\");\n\nconst root = process.cwd();\nlet assertions = 0;\nfunction read(relative) {\n  const file = path.join(root, ...relative.split(\"/\"));\n  if (!fs.existsSync(file)) throw new Error(`Arquivo não encontrado: ${relative}`);\n  return fs.readFileSync(file, \"utf8\");\n}\nfunction check(value, message) {\n  assertions += 1;\n  assert.ok(value, message);\n}\nfunction has(text, value, message) {\n  check(text.includes(value), message);\n}\n\nconst page = read(\"app/usuarios-sistema/page.tsx\");\nconst api = read(\"app/api/usuarios-sistema/route.ts\");\nconst apiId = read(\"app/api/usuarios-sistema/[id]/route.ts\");\nconst core = read(\"lib/server/usuariosSistemaCore.ts\");\nconst schema = read(\"prisma/schema.prisma\");\n\nhas(schema, \"profitShareEnabled Boolean @default(false)\", \"schema 3C.5A presente\");\nhas(schema, \"profitSharePercent Decimal @default(0)\", \"percentual no schema presente\");\n\nhas(core, \"profitShareEnabled: true\", \"select retorna flag\");\nhas(core, \"profitSharePercent: true\", \"select retorna percentual\");\nhas(core, \"participacaoLucroParaSalvar\", \"validador central existe\");\nhas(core, \"role !== SystemUserRole.TECNICO\", \"não técnico força participação desligada\");\nhas(core, \"recebido <= 0 || recebido > 100\", \"servidor valida faixa do percentual\");\nhas(core, \"Math.round(recebido * 100) / 100\", \"servidor arredonda a duas casas\");\nhas(core, \"profitShareEnabled ? Number(profitSharePercent || 0) : 0\", \"formatação normaliza Decimal\");\n\nhas(api, \"participacaoLucroParaSalvar(body, role)\", \"POST valida participação server-side\");\nhas(api, \"profitShareEnabled: profitShare.enabled\", \"POST salva flag validada\");\nhas(api, \"profitSharePercent: profitShare.percent\", \"POST salva percentual validado\");\n\nhas(apiId, \"participacaoLucroParaSalvar(body, role)\", \"PATCH valida participação server-side\");\nhas(apiId, \"profitShareEnabled: profitShare.enabled\", \"PATCH salva flag validada\");\nhas(apiId, \"profitSharePercent: profitShare.percent\", \"PATCH salva percentual validado\");\n\nhas(page, \"Participa do lucro das OS\", \"UI exibe configuração para técnico\");\nhas(page, \"Percentual do técnico *\", \"UI possui percentual\");\nhas(page, 'form.role === \"TECNICO\"', \"UI condiciona configuração ao perfil técnico\");\nhas(page, 'min=\"0.01\"', \"input possui mínimo\");\nhas(page, 'max=\"100\"', \"input possui máximo\");\nhas(page, 'step=\"0.01\"', \"input usa duas casas\");\nhas(page, \"profitShareEnabled:\", \"payload envia flag\");\nhas(page, \"profitSharePercent:\", \"payload envia percentual\");\nhas(page, \"Participação no lucro:\", \"lista mostra configuração\");\nhas(page, \"será congelado na própria OS\", \"UI explica snapshot histórico\");\n\ncheck(!api.includes(\"technicianProfitPercentSnapshot\"), \"API de usuários não grava snapshot de OS\");\ncheck(!apiId.includes(\"technicianProfitPercentSnapshot\"), \"PATCH de usuário não altera snapshot de OS\");\ncheck(!page.includes(\"technicianProfitPercentSnapshot\"), \"UI de usuários não manipula snapshot de OS\");\n\nconsole.log(JSON.stringify({\n  ok: true,\n  stage: \"3C.5B\",\n  assertions,\n  databaseChanged: false,\n  schemaChanged: false,\n  migrationRequired: false\n}));\n";

function abs(relative) {
  return path.join(root, ...relative.split("/"));
}
function required(relative) {
  const file = abs(relative);
  if (!fs.existsSync(file)) throw new Error(`Arquivo obrigatório não encontrado: ${relative}`);
  return fs.readFileSync(file, "utf8");
}
function sha256(text) {
  return crypto.createHash("sha256").update(Buffer.from(text, "utf8")).digest("hex");
}
function validateExact(relative) {
  const source = required(relative);
  if (sha256(source) !== expected[relative]) {
    throw new Error(`${relative} mudou desde a revisão. Nenhum arquivo será alterado; envie a versão atual.`);
  }
}
function backupAndWrite(relative, content, changed) {
  const file = abs(relative);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  if (fs.existsSync(file)) {
    const current = fs.readFileSync(file, "utf8");
    if (current === content) {
      console.log(`[OK JÁ ATUALIZADO] ${relative}`);
      return;
    }
    const backup = `${file}.bak-3c5b-${stamp}`;
    fs.copyFileSync(file, backup);
    console.log(`[BACKUP] ${path.basename(backup)}`);
  }
  fs.writeFileSync(file, content, "utf8");
  changed.push(relative);
  console.log(`[GRAVADO] ${relative}`);
}

function validatePrerequisites() {
  for (const relative of Object.keys(expected)) validateExact(relative);

  const schema = required("prisma/schema.prisma");
  if (
    !schema.includes("profitShareEnabled Boolean @default(false)") ||
    !schema.includes("profitSharePercent Decimal @default(0)")
  ) {
    throw new Error("A estrutura 3C.5A não foi encontrada no schema.");
  }
}

function main() {
  validatePrerequisites();

  const changed = [];
  for (const [relative, content] of Object.entries(targets)) {
    backupAndWrite(relative, content, changed);
  }
  backupAndWrite(testFile, testContent, changed);

  console.log(JSON.stringify({
    ok: true,
    stage: "3C.5B",
    changed,
    technicianOnly: true,
    enabledRange: "0.01..100.00",
    serverRoundsDecimals: 2,
    nonTechnicianPolicy: "force-disabled-zero",
    snapshotChanged: false,
    databaseChanged: false,
    schemaChanged: false,
    migrationRequired: false
  }));
}

main();
